<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;use App\Core\CSRF;
AccessControl::require('doctors.manage');$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){CSRF::verify();$type=$_POST['employment_type']??'full_time';$next=$type==='visiting'?($_POST['next_visit_date']?:null):null;$dur=$type==='visiting'?(int)($_POST['next_visit_duration']??0):null;
try{$q=Database::connection()->prepare("INSERT INTO doctors(doctor_number,name,telephone,room_number,employment_type,next_visit_date,next_visit_duration) VALUES(?,?,?,?,?,?,?)");$q->execute([trim($_POST['doctor_number']),trim($_POST['name']),trim($_POST['telephone']),trim($_POST['room_number']),$type,$next,$dur]);header('Location: /doctors/index.php');exit;}catch(Throwable $e){error_log($e->getMessage());$err='Could not save doctor. Check that the doctor number is unique.';}}
require dirname(__DIR__).'/_layout_top.php';?>
<h2>Add doctor</h2><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><?=CSRF::field()?><div class="row g-3"><?php foreach(['doctor_number'=>'Doctor number','name'=>'Full name','telephone'=>'Telephone','room_number'=>'Consulting room'] as $k=>$v):?><div class="col-md-6"><label class="form-label"><?=e($v)?></label><input class="form-control" name="<?=e($k)?>" required></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Employment type</label><select class="form-select" name="employment_type" id="type"><option value="full_time">Full-time</option><option value="visiting">Visiting</option></select></div><div class="col-md-6"><label class="form-label">Next visit date (visiting)</label><input class="form-control" type="date" name="next_visit_date"></div><div class="col-md-6"><label class="form-label">Visit duration in minutes</label><input class="form-control" type="number" min="1" name="next_visit_duration"></div></div><button class="btn btn-primary mt-4">Save doctor</button></form><?php require dirname(__DIR__).'/_layout_bottom.php';?>
